import json, time
from collections import Counter

def run_agent(goal, tools, call_model, max_steps=12, deadline_s=90, budget_tokens=60000):
    """tools: {name: {schema, fn}}"""
    messages = [{"role": "user", "content": goal}]
    action_sig = Counter()      # 用于检测重复动作
    tokens_used = 0
    t0 = time.time()

    for step in range(max_steps):
        # 终止条件 2：超时
        if time.time() - t0 > deadline_s:
            return {"status": "timeout", "steps": step, "messages": messages}
        # 终止条件 3：token 预算
        if tokens_used > budget_tokens:
            return {"status": "over_budget", "steps": step, "messages": messages}

        resp = call_model(messages, tools=[t["schema"] for t in tools.values()])
        tokens_used += resp.usage.total_tokens
        msg = resp.message
        messages.append(msg)

        calls = getattr(msg, "tool_calls", None) or []
        # 终止条件 1：没有工具调用 = 模型认为可以结束
        if not calls:
            return {"status": "done", "steps": step, "answer": msg.content}

        for c in calls:
            name, args = c.function.name, json.loads(c.function.arguments or "{}")

            # 终止条件 4：重复动作（同一工具 + 同一参数出现 3 次）
            sig = f"{name}:{json.dumps(args, sort_keys=True, ensure_ascii=False)}"
            action_sig[sig] += 1
            if action_sig[sig] >= 3:
                result = {"error": "REPEATED_ACTION",
                          "hint": "同一调用已重复 3 次。请换一种方式，或说明当前无法完成的原因。"}
            elif name not in tools:
                result = {"error": "UNKNOWN_TOOL", "hint": f"可用工具：{list(tools)}"}
            else:
                # 校验与执行都在应用侧（模型不执行任何东西）
                try:
                    result = tools[name]["fn"](**args)
                except TypeError as e:
                    result = {"error": "BAD_ARGS", "hint": str(e)[:200]}
                except Exception as e:
                    result = {"error": "EXEC_FAILED", "hint": str(e)[:200]}

            messages.append({
                "role": "tool", "tool_call_id": c.id,
                "content": json.dumps(result, ensure_ascii=False)[:4000],  # 截断长结果
            })

    # 终止条件 5：达到步数上限
    return {"status": "max_steps", "steps": max_steps, "messages": messages}

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("internal-kb")

@mcp.tool()
def search_docs(query: str, top_k: int = 5) -> list[dict]:
    """在企业知识库中检索文档片段。

    仅在用户询问公司制度、流程、产品参数时使用。
    若用户只给了模糊描述（如「那个报销的事」），先用 list_topics 确认主题。

    Args:
        query: 检索语句，用自然语言描述要找的内容
        top_k: 返回条数，1~10，默认 5
    """
    if not 1 <= top_k <= 10:
        raise ValueError("top_k 必须在 1~10 之间")   # 会作为错误返回给模型
    return kb.search(query, k=top_k)

@mcp.tool()
def list_topics() -> list[str]:
    """列出知识库涵盖的主题分类。当不确定该查什么时先用这个。"""
    return kb.topics()

@mcp.resource("doc://policy/{doc_id}")
def get_doc(doc_id: str) -> str://n    """读取指定文档的完整内容（由客户端决定是否放入上下文）"""
    return kb.get(doc_id)

@mcp.prompt()
def summarize_policy(doc_id: str) -> str:
    """生成「制度摘要」的提示模板（由用户主动选择）"""
    return f"请阅读 doc://policy/{doc_id}，用三点总结关键规定，并指出对普通员工的影响。"

if __name__ == "__main__":
    mcp.run(transport="stdio")     # 本地进程；远程改为 streamable-http

import time, json

class ToolError(Exception):
    def __init__(self, code, message, retryable=False, hint=None):
        self.code, self.message = code, message
        self.retryable, self.hint = retryable, hint
        super().__init__(message)

def call_tool(fn, args, schema=None, max_retry=2, fallback=None):
    """统一封装:校验 -> 分类重试 -> 降级 -> 结构化返回"""
    # ① 调用前校验（本地校验比等 API 报错快，也不浪费配额）
    if schema:
        try:
            schema.validate(args)
        except Exception as e:
            return {"ok": False, "error": "BAD_ARGS",
                    "hint": f"参数不符合 schema：{str(e)[:150]}。请修正后重试。"}

    last = None
    for attempt in range(max_retry + 1):
        try:
            return {"ok": True, "data": fn(**args)}
        except ToolError as e:
            last = e
            if not e.retryable:                      # 不可重试：立刻返回，让模型改参/换策略
                return {"ok": False, "error": e.code,
                        "hint": e.hint or e.message}
            if attempt < max_retry:
                time.sleep(2 ** attempt)             # 指数退避：1s, 2s
        except TimeoutError:
            last = ToolError("TIMEOUT", "调用超时", retryable=True)
            if attempt < max_retry:
                time.sleep(2 ** attempt)
        except Exception as e:                        # 未知异常：不重试，避免放大副作用
            return {"ok": False, "error": "UNEXPECTED",
                    "hint": f"工具内部异常，请换一种方式完成任务。{str(e)[:100]}"}

    # ② 重试耗尽 -> 降级
    if fallback:
        try:
            data = fallback(**args)
            return {"ok": True, "data": data, "degraded": True,
                    "hint": "实时数据不可用，已使用备用来源，回答时需说明。"}
        except Exception:
            pass

    # ③ 上报：明确失败 + 可操作信息
    return {"ok": False, "error": last.code if last else "UNKNOWN",
            "hint": f"已重试 {max_retry} 次仍失败。请换工具或说明无法完成的原因。"}
